// Discover a valid bool flag from the registry and register a validator for it.
// This enforces that the provided flag pointer is a real gflags-managed bool.
{
  std::vector<GFLAGS_NAMESPACE::CommandLineFlagInfo> flags;
  GFLAGS_NAMESPACE::GetAllFlags(&flags);
  if (flags.empty()) { FUZZ_BAIL(); }

  // Find a bool flag with a non-null storage pointer.
  const GFLAGS_NAMESPACE::CommandLineFlagInfo* chosen = nullptr;
  for (size_t i = 0; i < flags.size(); ++i) {
    if (flags[i].type == "bool" && flags[i].flag_ptr != nullptr) { chosen = &flags[i]; break; }
  }
  if (!chosen) { FUZZ_BAIL(); }

  // Create a non-capturing validator lambda convertible to a function pointer.
  // It will accept any value except possibly flip behavior based on the flag name length.
  bool (*validator)(const char*, bool) = +[](const char* name, bool value) -> bool {
    // Basic sanity: name must be non-null, but the API may call with a valid name.
    if (!name) return false;
    // Accept values generally; reject only for odd-length names and false value to explore both paths.
    size_t len = 0; for (const char* p = name; *p; ++p) ++len;
    if ((len & 1u) && value == false) return false;
    return true;
  };

  // Register the validator. API returns false on failure (e.g., already has a validator).
  (void)GFLAGS_NAMESPACE::RegisterFlagValidator(static_cast<const bool*>(chosen->flag_ptr), validator);
}
// Validation: We only attempt registration for a discovered bool flag with non-null storage; otherwise we bail to avoid invalid pointers.

