// Set the value of an existing flag using a type-appropriate textual value.
{
  std::vector<GFLAGS_NAMESPACE::CommandLineFlagInfo> all;
  GFLAGS_NAMESPACE::GetAllFlags(&all);
  if (all.empty()) { FUZZ_BAIL(); }
  size_t idx = static_cast<size_t>(*FUZZ_PARAM(unsigned)) % all.size();
  const GFLAGS_NAMESPACE::CommandLineFlagInfo& f = all[idx];

  // Generate a value string compatible with the flag's type.
  std::string val;
  if (f.type == "bool") {
    val = ((*FUZZ_PARAM(unsigned) & 1u) ? "true" : "false");
  } else if (f.type == "int32" || f.type == "int64") {
    long long n = static_cast<long long>(*FUZZ_PARAM(int));
    val = std::to_string(n);
  } else if (f.type == "uint32" || f.type == "uint64") {
    unsigned long long u = static_cast<unsigned long long>(*FUZZ_PARAM(unsigned));
    val = std::to_string(u);
  } else if (f.type == "double") {
    double d = *FUZZ_PARAM(double);
    // Constrain magnitude to avoid infinities/NaNs in some libcs.
    if (d != d) d = 0.0; // NaN guard
    if (d > 1e300) d = 1e300; if (d < -1e300) d = -1e300;
    val = std::to_string(d);
  } else if (f.type == "string") {
    std::string s = FUZZ_PARAM_STR();
    val.assign(s.data(), s.size());
  } else {
    // Unknown type; bail rather than risk UB.
    FUZZ_BAIL();
  }

  std::string res = GFLAGS_NAMESPACE::SetCommandLineOption(f.name.c_str(), val.c_str());
