// Perform a full parse of command-line flags, constructing argc/argv.
{
  // Build a small argv with program name and a few well-formed flag args from the registry.
  std::vector<GFLAGS_NAMESPACE::CommandLineFlagInfo> reg;
  GFLAGS_NAMESPACE::GetAllFlags(&reg);

  std::vector<std::string> storage;
  std::vector<char*> argv_vec;
  storage.reserve(8); argv_vec.reserve(8);
  // argv[0]
  storage.emplace_back(FUZZ_PARAM_STR()); if (storage.back().empty()) storage.back() = "prog";
  argv_vec.push_back(const_cast<char*>(storage.back().c_str()));

  // Add up to 3 flags with type-appropriate values
  unsigned add_n = reg.empty() ? 0u : (*FUZZ_PARAM(unsigned) % 3u);
  for (unsigned i = 0; i < add_n && !reg.empty(); ++i) {
    const GFLAGS_NAMESPACE::CommandLineFlagInfo& f = reg[*FUZZ_PARAM(unsigned) % reg.size()];
    std::string val;
    if (f.type == "bool") {
      val = ((*FUZZ_PARAM(unsigned) & 1u) ? "true" : "false");
    } else if (f.type == "int32" || f.type == "int64") {
