import random
import string
from typing import List

# This generator produces interesting C strings (null-terminated when passed via c_str())
# suitable for const char* parameters used across the provided fuzz stubs. It focuses on
# program names, filenames, and general argv tokens, aiming to trigger diverse code paths
# in gflags without malformed data.

MAX_BYTES = 4096

_prog_names = [
    "prog", "app", "tool", "server", "cli", "gflags_tester",
    "/usr/bin/prog", "C:/Program Files/App/app.exe", "./run", "../bin/tool",
]

# Filenames to exercise different OS/path styles and characters
_file_names = [
    "/tmp/flags.txt", "/tmp/.hidden", "/var/tmp/f.cfg", "/tmp/flagfile.conf",
    "flagfile.txt", "./flags", "../flags.d/flags.conf", "NUL", "CON", "PRN",
    "C:/temp/flags.txt", "C:/Windows/Temp/f.txt",
]

# Substrings for ShowUsageWithFlagsRestrict (filename filters)
_restrict_filters = [
    "", "flags", "help", "version", "gflags", ".cc", ".h", "main", "/tmp/", "src/",
]

_bool_vals = ["true", "false", "1", "0", "t", "f", "True", "False"]

# Utility: generate a random ASCII chunk without NULs

def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    # Favor sensible shell/argv characters plus some punctuation
    alphabet = string.ascii_letters + string.digits + "-_./:@,+=%[]{}()\"'"
    return "".join(r.choice(alphabet) for _ in range(n))

# Utility: generate a number string (int/uint/float) with interesting edges

def _num_string(r: random.Random) -> str:
    choice = r.randint(0, 8)
    if choice == 0:
        return str(0)
    if choice == 1:
        return str(-1)
    if choice == 2:
        return str(1 << 31)
    if choice == 3:
        return str((1 << 31) - 1)
    if choice == 4:
        return str(1 << 32)
    if choice == 5:
        return str((1 << 63) - 1)
    if choice == 6:
        return str(-(1 << 63) + 1)
    if choice == 7:
        # double, constrained magnitude
        d = r.uniform(-1e6, 1e6)
        return f"{d:.6f}"
    # generic int
    return str(r.randint(-10_000_000, 10_000_000))

# Construct a flag assignment token suitable for argv: --name=value
# We cannot know concrete flag names at generation time, so we emit a mix of
# commonly seen names and syntactically valid placeholders. The stubs also
# build their own argv; our buffer is used for FUZZ_PARAM_STR or filenames.
# Still, providing realistic flag-like strings helps exercise string paths.

def _flag_token(r: random.Random) -> str:
    names = [
        "help", "helpshort", "version", "v", "logtostderr", "colorlogtostderr",
        "vmodule", "minloglevel", "alsologtoemail", "flagfile", "undefok",
        "max_idle", "timeout_ms", "rate", "name", "path", "config",
    ]
    name = r.choice(names + ["flag_" + _rand_ascii(r, 3, 8).lower()])
    # value type selection
    t = r.randint(0, 4)
    if t == 0:
        val = r.choice(_bool_vals)
    elif t == 1:
        val = _num_string(r)
    elif t == 2:
        val = _rand_ascii(r, 0, 12)
    elif t == 3:
        # path-like
        val = r.choice(_file_names)
    else:
        val = r.choice(_restrict_filters)
    return f"--{name}={val}"

# Build a composite buffer containing several null-terminated C-strings
# concatenated by newlines, which the harness will slice via FUZZ_PARAM_STR
# or use as filenames via FUZZ_PARAM_FILENAME. We avoid embedded NULs.

def _build_buffer(r: random.Random) -> bytes:
    parts: List[str] = []

    # 1) Program name candidates
    parts.append(r.choice(_prog_names))
    # Provide variants with and without paths
    if r.random() < 0.7:
        parts.append(_rand_ascii(r, 3, 12))

    # 2) Restrict filters
    parts.extend(r.sample(_restrict_filters, k=min(3, len(_restrict_filters))))

    # 3) Filenames for flag files and append output
    # Include both absolute and relative paths and Windows-like paths
    for _ in range(r.randint(2, 5)):
        if r.random() < 0.5:
            parts.append(r.choice(_file_names))
        else:
            # synthesize a path
            if r.random() < 0.5:
                # Unix-ish
                path = "/" + "/".join(_rand_ascii(r, 1, 6).lower() for _ in range(r.randint(1, 3)))
                if r.random() < 0.5:
                    path += "." + r.choice(["txt", "conf", "flags", "cfg"]) 
            else:
                # Windows-ish
                drive = r.choice(["C:", "D:", "E:"])
                segs = [ _rand_ascii(r, 1, 6) for _ in range(r.randint(1, 3)) ]
                path = drive + "/" + "/".join(segs)
                if r.random() < 0.6:
                    path += "." + r.choice(["txt", "conf", "cfg"]) 
            parts.append(path)

    # 4) Flag-like tokens to seed argv construction within the target
    for _ in range(r.randint(2, 6)):
        parts.append(_flag_token(r))

    # 5) Some plain strings for SetArgv positional args and string flags
    for _ in range(r.randint(2, 5)):
        parts.append(_rand_ascii(r, 0, 20))

    # 6) Include explicit boolean/number strings to feed type-specific paths
    parts.extend(r.sample(_bool_vals, k=min(4, len(_bool_vals))))
    for _ in range(4):
        parts.append(_num_string(r))

    # Ensure non-empty and size-bounded
    joined = "\n".join(parts)
    data = joined.encode('utf-8', errors='ignore')
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]
    return data


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return _build_buffer(r)

import random
import string
from typing import List

def _rand_bool(r: random.Random) -> bool:
    return r.choice([True, False])

def _rand_int(r: random.Random, bits: int = 32, signed: bool = True) -> int:
    if bits == 32:
        if signed:
            return r.randint(-2**31, 2**31 - 1)
        else:
            return r.randint(0, 2**32 - 1)
    elif bits == 64:
        if signed:
            return r.randint(-2**63, 2**63 - 1)
        else:
            return r.randint(0, 2**64 - 1)
    else:
        # fallback small range
        lo, hi = (-9999, 9999) if signed else (0, 9999)
        return r.randint(lo, hi)

def _rand_double(r: random.Random) -> float:
    # Cover interesting doubles: normals, subnormals-ish magnitudes, infinities-like strings are not valid here
    # so stick to finite numbers, but include edge magnitudes and precise decimals
    choices = [
        0.0, -0.0, 1.0, -1.0, 3.141592653589793, -2.718281828459045,
        r.uniform(-1e-300, 1e-300), r.uniform(-1e-10, 1e-10),
        r.uniform(-1e10, 1e10)
    ]
    return r.choice(choices)

def _rand_word(r: random.Random, min_len=3, max_len=12) -> str:
    alphabet = string.ascii_letters + string.digits + "_-"
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(alphabet) for _ in range(n))

def _rand_path(r: random.Random) -> str:
    # Generate a plausible filename or path-like token
    parts = []
    depth = r.randint(1, 3)
    for _ in range(depth):
        parts.append(_rand_word(r, 1, 8))
    return '/'.join(parts)

def _escape_string_value(s: str) -> str:
    # gflags flagfiles accept --flag=value without quoting; embed spaces via escaping using backslashes
    # We keep it simple: replace newlines with spaces; escape spaces and tabs
    s = s.replace('\n', ' ').replace('\r', '')
    s = s.replace('\t', '\\t').replace(' ', '\\ ')
    return s

def _make_bool_value(r: random.Random) -> str:
    # gflags accepts true/false variations and 0/1
    forms_true = ['true', 't', '1', 'True', 'TRUE']
    forms_false = ['false', 'f', '0', 'False', 'FALSE']
    return r.choice(forms_true if _rand_bool(r) else forms_false)

def _make_string_value(r: random.Random) -> str:
    # Create diverse string forms likely to be accepted as values
    kind = r.randint(0, 5)
    if kind == 0:
        s = _rand_word(r, 0, 24)  # may be empty
    elif kind == 1:
        s = 'v' * r.randint(0, 64)
    elif kind == 2:
        # path-like
        s = _rand_path(r)
    elif kind == 3:
        # mixed with punctuation that is safe without quoting
        alphabet = string.ascii_letters + string.digits + "_-.,:/@"
        n = r.randint(0, 48)
        s = ''.join(r.choice(alphabet) for _ in range(n))
    elif kind == 4:
        # words with spaces escaped
        words = [_rand_word(r, 1, 8) for _ in range(r.randint(1, 5))]
        s = ' '.join(words)
    else:
        s = 'hello_world'
    return _escape_string_value(s)

def _make_numeric_string(r: random.Random, bits: int, signed: bool) -> str:
    return str(_rand_int(r, bits, signed))

def _make_double_string(r: random.Random) -> str:
    # Use repr-like formatting to keep precision; avoid inf/nan
    val = _rand_double(r)
    # Occasionally force scientific notation
    if r.random() < 0.4:
        return f"{val:.16e}"
    else:
        return f"{val:.17g}"

def _pick_flag_name(r: random.Random, ftype: str) -> str:
    # Generate plausible flag names; include type hints in names sometimes
    base = r.choice([
        'verbose', 'logtostderr', 'max_items', 'timeout_ms', 'seed', 'ratio',
        'config', 'path', 'data_dir', 'output', 'enable_feature', 'threshold',
        'buffer_size', 'retry', 'count', 'max_bytes', 'min_bytes', 'port',
        'host', 'mode', 'user', 'password', 'color', 'precision', 'factor'
    ])
    suffix = ''
    if ftype == 'bool':
        suffix = r.choice(['', '', '', '_enabled', '_flag'])
    elif ftype in ('int32', 'uint32', 'int64', 'uint64'):
        suffix = r.choice(['', '_limit', '_count', '_bytes', '_ms'])
    elif ftype == 'double':
        suffix = r.choice(['', '_ratio', '_threshold'])
    elif ftype == 'string':
        suffix = r.choice(['', '_file', '_dir', '_name', '_path'])
    # Add random prefix/scope variations sometimes
    prefix = ''
    if r.random() < 0.15:
        prefix = r.choice(['app_', 'lib_', 'sys_', 'exp_'])
    name = prefix + base + suffix
    # gflags names usually use underscores; sometimes include dash
    if r.random() < 0.1:
        name = name.replace('_', '-')
    return name

def _emit_flag_line(name: str, value: str, comment: str | None = None) -> str:
    line = f"--{name}={value}"
    if comment:
        line += f"  # {comment}"
    return line

def _make_flag_lines(r: random.Random) -> List[str]:
    lines: List[str] = []
    # Header comments and blank lines
    if r.random() < 0.8:
        lines.append("# Autogenerated flagfile snapshot")
    if r.random() < 0.5:
        lines.append("")

    # Number of flags
    n = r.randint(5, 40)

    # Ensure coverage of types
    type_cycle = ['bool', 'int32', 'uint32', 'int64', 'uint64', 'double', 'string']

    for i in range(n):
        ftype = r.choice(type_cycle) if r.random() < 0.7 else r.choice(type_cycle)
        name = _pick_flag_name(r, ftype)
        if ftype == 'bool':
            val = _make_bool_value(r)
        elif ftype == 'int32':
            val = _make_numeric_string(r, 32, True)
        elif ftype == 'uint32':
            val = _make_numeric_string(r, 32, False)
        elif ftype == 'int64':
            val = _make_numeric_string(r, 64, True)
        elif ftype == 'uint64':
            val = _make_numeric_string(r, 64, False)
        elif ftype == 'double':
            val = _make_double_string(r)
        else:
            val = _make_string_value(r)
        comment = None
        if r.random() < 0.25:
            comment = r.choice([
                'set by generator', 'tuned for test', 'auto', 'snapshot', None
            ])
        lines.append(_emit_flag_line(name, val, comment))
        # Occasionally add inline comments or whitespace lines
        if r.random() < 0.15:
            lines.append("")
        if r.random() < 0.2:
            lines.append(f"# note: {name} configured")

    # Add includes of other flagfiles like @file syntax is not part of this interface; keep to basic lines
    # Footer
    if r.random() < 0.4:
        lines.append("# End of flags")

    return lines

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Optionally prepend a usage/version descriptive comment block
    prelude = []
    if r.random() < 0.6:
        prog = _rand_word(r, 3, 12)
        prelude.append(f"# Program: {prog}")
    if r.random() < 0.4:
        prelude.append("# Generated by gflags-friendly generator")

    lines = prelude + _make_flag_lines(r)

    text = "\n".join(lines) + "\n"

    # Enforce max size 4096 bytes by trimming comment lines first
    b = text.encode('utf-8', errors='ignore')
    if len(b) > 4096:
        # Try to remove comment lines to shrink
        non_comment = [ln for ln in lines if not ln.strip().startswith('#')]
        text2 = "\n".join(non_comment) + "\n"
        b = text2.encode('utf-8', errors='ignore')
        if len(b) > 4096:
            # Hard trim to limit
            b = b[:4096]
            # ensure we end with newline for cleanliness
            if not b.endswith(b"\n"):
                b = b[:-1] + b"\n"

    return b

import os
import random
import string
from typing import List

# This generator targets fuzzer stubs expecting:
# - FUZZ_PARAM_FILENAME(): path to a readable/writable file
# - FUZZ_PARAM_STR(): program name string (non-null)
# It encodes two fields sequentially as UTF-8 text separated by "\n\0" delimiters:
#   [filename]\n\0[prog_name]\n\0
# Size is capped at 4096 bytes. No external I/O is performed.

SAFE_FN_CHARS = string.ascii_letters + string.digits + "-_.,@#%+=^(){}!$'`~"
# Exclude path separators from name characters
SAFE_NAME_CHARS = SAFE_FN_CHARS.replace(os.sep, '')
if os.path.altsep:
    SAFE_NAME_CHARS = SAFE_NAME_CHARS.replace(os.path.altsep, '')

EXTENSIONS = [
    "", ".txt", ".log", ".flags", ".cfg", ".conf", ".ini", ".json", ".yaml",
    ".dat", ".bin", ".tmp"
]

PROG_TEMPLATES = [
    "prog", "app", "test", "fuzz_target", "gflags_tool", "cli", "runner",
    "微程序", "программа", "برنامج", "ツール"
]

def _rand(r: random.Random, nmin: int, nmax: int) -> int:
    return r.randint(nmin, nmax)

def _rand_name(r: random.Random, min_len: int = 1, max_len: int = 16, allow_dot_prefix: bool = True) -> str:
    length = _rand(r, min_len, max_len)
    s = ''.join(r.choice(SAFE_NAME_CHARS) for _ in range(length))
    if allow_dot_prefix and r.random() < 0.2:
        prefix = r.choice([".", "..", ".hidden", ".config"])
        s = prefix + s
    return s[:max_len]

def _rand_dirs(r: random.Random) -> List[str]:
    parts = []
    depth = _rand(r, 0, 3)
    for _ in range(depth):
        parts.append(_rand_name(r, 1, _rand(r, 3, 10), allow_dot_prefix=True))
    return parts

def _rand_extension(r: random.Random) -> str:
    return r.choice(EXTENSIONS)

def _make_relative_path(r: random.Random) -> str:
    parts = _rand_dirs(r)
    base = _rand_name(r, 1, _rand(r, 3, 20), allow_dot_prefix=True)
    ext = _rand_extension(r)
    name = base + ext
    parts.append(name)
    return os.path.join(*parts) if parts else name

def _make_absolute_path(r: random.Random) -> str:
    # Absolute paths may not be writable, but included for variety.
    if os.name == 'nt':
        if r.random() < 0.5:
            drive = r.choice(string.ascii_uppercase)
            path_after = _make_relative_path(r).replace(':', '_')
            # Avoid backslashes inside f-string expressions by concatenation
            return drive + ":\\" + path_after.replace('/', '\\')
        else:
            return "\\" + _make_relative_path(r).replace('/', '\\')
    else:
        return "/" + _make_relative_path(r)

def _candidate_paths(r: random.Random) -> List[str]:
    cands = []
    cands.append(_make_relative_path(r))
    cands.append(os.path.join("tmp", _make_relative_path(r)))
    cands.append(os.path.join(".", _make_relative_path(r)))
    if r.random() < 0.4:
        cands.append(_make_absolute_path(r))
    cands.append(_rand_name(r, 1, 3) + _rand_extension(r))
    cands.append(_rand_name(r, 10, 40) + _rand_extension(r))
    cands.append(os.path.join(_rand_name(r, 1, 6), _rand_name(r, 1, 12) + _rand_extension(r)))
    return cands

def _sanitize_path(p: str) -> str:
    p = p.strip("\0\n\r")
    if not p:
        p = "file.flags"
    # Remove trailing separators
    while p.endswith(os.sep) or (os.path.altsep and p.endswith(os.path.altsep)):
        p = p[:-1] or "file.flags"
    return p[:256]

def _make_prog_name(r: random.Random) -> str:
    base = r.choice(PROG_TEMPLATES)
    suffix = ''
    if r.random() < 0.7:
        suffix = '-' + str(_rand(r, 0, 9999))
    ext = ''
    if os.name == 'nt' and r.random() < 0.6:
        ext = r.choice([".exe", ".cmd", ".bat", ""])
    elif r.random() < 0.3:
        ext = r.choice(["", ".sh", ".py"])
    name = base + suffix + ext
    if r.random() < 0.5:
        if os.name == 'nt':
            dir_options = [".\\", "..\\", "C:\\Program Files\\"]
        else:
            dir_options = ["./", "../", "/usr/bin/", "/bin/"]
        dir_part = r.choice(dir_options)
        name = dir_part + name
    return name.replace('\0', '')[:256] or "prog"

def _encode_fields(fields: List[str]) -> bytes:
    out = bytearray()
    for f in fields:
        f = f.replace('\0', ' ')
        out.extend(f.encode('utf-8', errors='ignore'))
        out.extend(b"\n\0")
    return bytes(out)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    candidates = _candidate_paths(r)
    path = _sanitize_path(r.choice(candidates))
    if r.random() < 0.2:
        path = "flags.out"
    prog = _make_prog_name(r)
    blob = _encode_fields([path, prog])
    return blob[:4096]

import random
import string
import struct

# Generator for a single argv entry string (command-line argument)
# Target stubs will call FUZZ_PARAM_STR() to fill argv[0], flag args, and
# optional positional args. Provide a rich mix of valid patterns.

_MAX_LEN = 4096

_bool_vals = ["true", "false", "1", "0", "t", "f", "True", "False"]
_prog_names = [
    "prog", "app", "tool", "gflags_demo", "bin/runner", "./a.out",
    "/usr/local/bin/tester", "C:/Program Files/App/app.exe"
]

# Common flag name patterns seen in gflags-based projects
_flag_name_parts = [
    "log", "v", "verbose", "color", "threads", "timeout", "size",
    "limit", "port", "host", "path", "mode", "seed", "rate", "ratio",
    "retries", "threshold", "enable", "disable", "buffer", "window",
    "level", "cache", "debug", "trace", "max", "min"
]

_file_like_values = [
    "/tmp/file.txt", "/var/log/app.log", "C:/temp/in.txt", "./data.bin",
    "../relative/path.cfg", "/etc/hosts"
]

_positional_samples = [
    "input.txt", "--", "subcommand", "payload", "/dev/null", "-", "arg",
    "foo", "bar", "baz", "日本語", "spaced value", "quoted\ value"
]

def _rand_ident(rng: random.Random, min_parts=1, max_parts=3) -> str:
    parts = []
    for _ in range(rng.randint(min_parts, max_parts)):
        base = rng.choice(_flag_name_parts)
        # occasionally add suffix/prefix
        if rng.random() < 0.3:
            base += str(rng.randint(0, 9))
        if rng.random() < 0.2:
            base = base.replace("e", "_", 1)
        parts.append(base)
    return "_".join(parts)

def _rand_prog_name(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return rng.choice(_prog_names)
    # generate a custom looking path/name
    name = ''.join(rng.choice(string.ascii_letters + string.digits + "-_") for _ in range(rng.randint(3, 10)))
    if rng.random() < 0.5:
        return "./" + name
    return name

def _rand_string_value(rng: random.Random) -> str:
    # include spaces, punctuation, unicode, and file-like paths
    choices = []
    if rng.random() < 0.4:
        choices.append(rng.choice(_file_like_values))
    if rng.random() < 0.3:
        choices.append(":".join([_rand_ident(rng), _rand_ident(rng)]))
    # random free-form string
    alphabet = string.ascii_letters + string.digits + string.punctuation + " "
    s = ''.join(rng.choice(alphabet) for _ in range(rng.randint(0, 24)))
    choices.append(s)
    # some unicode
    if rng.random() < 0.3:
        choices.append("παράμετρος")
    if rng.random() < 0.2:
        choices.append("路径/文件")
    return rng.choice(choices)

def _rand_int(rng: random.Random, bits=32, signed=True) -> int:
    if bits == 32:
        if signed:
            candidates = [0, -1, 1, 2147483647, -2147483648]
            if rng.random() < 0.6:
                return rng.choice(candidates)
            return rng.randint(-2**31, 2**31 - 1)
        else:
            candidates = [0, 1, 4294967295]
            if rng.random() < 0.6:
                return rng.choice(candidates)
            return rng.randint(0, 2**32 - 1)
    if bits == 64:
        if signed:
            candidates = [0, -1, 1, 9223372036854775807, -9223372036854775808]
            if rng.random() < 0.6:
                return rng.choice(candidates)
            return rng.randint(-2**63, 2**63 - 1)
        else:
            candidates = [0, 1, 18446744073709551615]
            if rng.random() < 0.6:
                return rng.choice(candidates)
            return rng.randint(0, 2**64 - 1)
    return rng.randint(-1000, 1000)

def _rand_double(rng: random.Random) -> str:
    # produce finite doubles within the clamped range used by stub
    special = [0.0, 1.0, -1.0, 1e-10, -1e-10, 1e300, -1e300, 3.1415926535]
    if rng.random() < 0.6:
        v = rng.choice(special)
    else:
        v = rng.uniform(-1e300, 1e300)
    # Use a format commonly accepted by gflags' double parser
    return ("%.*g" % (rng.randint(6, 17), v))

def _make_flag_arg(rng: random.Random) -> str:
    # pick a type and build --name=value accordingly
    t = rng.choices(
        population=["bool", "int32", "uint32", "int64", "uint64", "double", "string"],
        weights=[12, 14, 10, 12, 10, 12, 30],
        k=1
    )[0]
    name = _rand_ident(rng)
    if t == "bool":
        val = rng.choice(_bool_vals)
    elif t == "int32":
        val = str(_rand_int(rng, 32, True))
    elif t == "uint32":
        val = str(_rand_int(rng, 32, False))
    elif t == "int64":
        val = str(_rand_int(rng, 64, True))
    elif t == "uint64":
        val = str(_rand_int(rng, 64, False))
    elif t == "double":
        val = _rand_double(rng)
    else:  # string
        val = _rand_string_value(rng)
    return f"--{name}={val}"

def _make_positional(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return rng.choice(_positional_samples)
    # arbitrary token without leading dashes to be a non-flag
    token = ''.join(rng.choice(string.ascii_letters + string.digits + "-_./") for _ in range(rng.randint(1, 20)))
    if token.startswith("-"):
        token = token.lstrip("-") or "arg"
    return token

def _build_argv_sequence(rng: random.Random) -> list[str]:
    argv = []
    argv0 = _rand_prog_name(rng)
    argv.append(argv0)
    # up to 3 flags as per stub
    n_flags = rng.randint(0, 3)
    for _ in range(n_flags):
        argv.append(_make_flag_arg(rng))
    # up to 2 positional args as per stub
    n_pos = rng.randint(0, 2)
    for _ in range(n_pos):
        argv.append(_make_positional(rng))
    return argv

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    argv = _build_argv_sequence(rng)
    # The fuzzer stub consumes one FUZZ_PARAM_STR at a time; return one entry.
    # To provide variability, pick a random element from the constructed argv.
    choice = rng.choice(argv)
    data = choice.encode('utf-8', errors='surrogatepass')
    if len(data) > _MAX_LEN:
        data = data[:_MAX_LEN]
    return data
